      case RebaseOutcome_Rebased(commit: final commit, commits: final commits):
        sse_encode_i_32(2, serializer);
        sse_encode_String(commit, serializer);
        sse_encode_u_32(commits, serializer);
      case RebaseOutcome_Conflicts(
        commit: final commit,
        conflicts: final conflicts,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(commit, serializer);
        sse_encode_list_conflict(conflicts, serializer);
    }
  }

  @protected
  void sse_encode_remote_options(RemoteOptions self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_auth(self.auth, serializer);
    sse_encode_list_String(self.trustedHostKeys, serializer);
  }

  @protected
  void sse_encode_transfer_event(TransferEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case TransferEvent_Progress(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_progress(field0, serializer);
      case TransferEvent_Done():
        sse_encode_i_32(1, serializer);
      case TransferEvent_Failed(field0: final field0):
        sse_encode_i_32(2, serializer);
        sse_encode_box_autoadd_core_error(field0, serializer);
    }
  }

  @protected
  void sse_encode_tree_file(TreeFile self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.path, serializer);
    sse_encode_String(self.blob, serializer);
    sse_encode_u_64(self.size, serializer);
    sse_encode_bool(self.link, serializer);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_64(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }
}
